import React from "react";
import { fireEvent, render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./Pagination.stories";
import Pagination from "./Pagination";

const { Legend } = composeStories(stories) as any;

describe("Pagination component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Legend />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("shows an ellipsis on the right side when there are too much pages", () => {
    render(
      <Pagination
        page={1}
        count={80}
        rowsPerPage={10}
        onPageChange={(_, page) => {}}
      />
    );
    // prev disabled button
    const prev = screen.getByLabelText(/Previous/);
    expect(prev).toBeDefined();
    expect(prev.getAttribute("disabled")).toEqual("");
    expect(screen.getByLabelText(/Next/)).toBeDefined();
    // active page1
    const page1 = screen.getByLabelText(/Page 1/);
    expect(page1.getAttribute("aria-current")).toEqual("page");
    // page 2/3/4 visible
    expect(screen.getByLabelText(/Page 2/)).toBeDefined();
    expect(screen.getByLabelText(/Page 3/)).toBeDefined();
    expect(screen.getByLabelText(/Page 4/)).toBeDefined();
    // right ellipsis
    expect(screen.getAllByText("…")).toHaveLength(1);
  });

  it("shows an ellipsis on the left side when there are too much pages", () => {
    render(
      <Pagination
        page={7}
        count={80}
        rowsPerPage={10}
        onPageChange={(_, page) => {}}
      />
    );
    expect(screen.getByLabelText(/Previous/)).toBeDefined();
    expect(screen.getByLabelText(/Next/)).toBeDefined();
    const page1 = screen.getByLabelText(/Page 7/);
    expect(page1.getAttribute("aria-current")).toEqual("page");
    expect(screen.getByLabelText(/Page 4/)).toBeDefined();
    expect(screen.getByLabelText(/Page 5/)).toBeDefined();
    expect(screen.getByLabelText(/Page 6/)).toBeDefined();
    expect(screen.getAllByText("…")).toHaveLength(1);
  });

  it("shows an ellipsis on both sides when there are too much pages", () => {
    render(
      <Pagination
        page={5}
        count={100}
        rowsPerPage={10}
        onPageChange={(_, page) => {}}
      />
    );
    expect(screen.getByLabelText(/Previous/)).toBeDefined();
    expect(screen.getByLabelText(/Next/)).toBeDefined();
    const page1 = screen.getByLabelText(/Page 5/);
    expect(page1.getAttribute("aria-current")).toEqual("page");
    expect(screen.getByLabelText(/Page 4/)).toBeDefined();
    expect(screen.getByLabelText(/Page 6/)).toBeDefined();
    expect(screen.getAllByText("…")).toHaveLength(2);
    screen.getAllByText("…").forEach((ellipsis) => {
      expect(ellipsis.closest("button")).toHaveAttribute("aria-hidden", "true");
    });
  });

  it("passes through props", () => {
    render(
      <Pagination
        data-testid="pagination"
        page={1}
        count={70}
        rowsPerPage={10}
        onPageChange={(_, page) => {}}
      />
    );
    expect(screen.getByTestId("pagination")).toBeTruthy();
  });

  it("Show only one item #799", () => {
    render(
      <Pagination
        page={1}
        count={10}
        rowsPerPage={10}
        onPageChange={(_, page) => {}}
      />
    );
    expect(screen.getByLabelText(/Previous/).getAttribute("disabled")).toEqual(
      ""
    );
    expect(screen.getByLabelText(/Next/).getAttribute("disabled")).toEqual("");
    expect(screen.getAllByLabelText(/Page/)).toHaveLength(1);
  });

  it("Show only two items #799", () => {
    render(
      <Pagination
        page={1}
        count={20}
        rowsPerPage={10}
        onPageChange={(_, page) => {}}
      />
    );
    const prev = screen.getByLabelText(/Previous/);
    const next = screen.getByLabelText(/Next/);
    expect(prev.getAttribute("disabled")).toEqual("");
    expect(next.getAttribute("disabled")).toBeNull();
    expect(screen.getAllByLabelText(/Page/)).toHaveLength(2);
  });

  it("No ellipsis with 7 pages #1294", () => {
    render(
      <Pagination
        page={1}
        count={35}
        rowsPerPage={5}
        onPageChange={(_, page) => {}}
      />
    );
    const prev = screen.getByLabelText(/Previous/);
    const next = screen.getByLabelText(/Next/);
    expect(prev.getAttribute("disabled")).toEqual("");
    expect(next.getAttribute("disabled")).toBeNull();
    expect(screen.getAllByLabelText(/Page/)).toHaveLength(7);
    expect(screen.queryByText("…")).not.toBeInTheDocument();
  });

  it("Resets gotopage when updating entries per page #1484", async () => {
    const onPageChange = jest.fn();
    const onRowsPerPageChange = jest.fn();
    render(
      <Pagination
        page={0}
        count={200}
        rowsPerPage={10}
        showGoto
        showRowsPerPage
        onPageChange={onPageChange}
        onRowsPerPageChange={onRowsPerPageChange}
      />
    );
    // goto page 15
    fireEvent.click(screen.getByRole("button", { name: /toggle menu/i }));
    fireEvent.click(screen.getByRole("option", { name: "15" }));
    expect(onPageChange).toHaveBeenCalledTimes(1);
    expect(onPageChange).toHaveBeenLastCalledWith(expect.anything(), 15);

    // change entries per page
    const rowsPerPageSelect = screen.getAllByRole("combobox")[0];
    fireEvent.change(rowsPerPageSelect, { target: { value: "100" } });
    expect(onRowsPerPageChange).toHaveBeenCalledTimes(1);
    expect(onRowsPerPageChange).toHaveBeenLastCalledWith(
      expect.anything(),
      "100"
    );

    // check that gotopage has been reset
    expect(screen.getByRole("combobox", { expanded: false })).toHaveValue("");
  });

  it("Provides accessible names for pagination inputs", () => {
    render(
      <Pagination
        page={1}
        count={200}
        rowsPerPage={10}
        showGoto
        showRowsPerPage
        onPageChange={(_, page) => {}}
        onRowsPerPageChange={(_, value) => {}}
      />
    );

    expect(screen.getByRole("combobox", { name: "Entries per page" })).toBeInTheDocument();
    expect(screen.getByRole("combobox", { name: "Go to page" })).toBeInTheDocument();
  });

  it("Resets gotopage when navigating pages #1798", async () => {
    const onPageChange = jest.fn();
    const { rerender } = render(
      <Pagination
        page={1}
        count={200}
        rowsPerPage={10}
        showGoto
        onPageChange={onPageChange}
      />
    );

    // goto page 15
    fireEvent.click(screen.getByRole("button", { name: /toggle menu/i }));
    fireEvent.click(screen.getByRole("option", { name: "15" }));

    // rerender with new page
    rerender(
      <Pagination
        page={15}
        count={200}
        rowsPerPage={10}
        showGoto
        onPageChange={onPageChange}
      />
    );

    // click on page 14
    fireEvent.click(screen.getByRole("button", { name: "Page 14" }));

    // check that gotopage has been reset
    expect(screen.getByRole("combobox", { expanded: false })).toHaveValue("");
  });

  it("Moves focus to active last page when next becomes disabled", () => {
    const onPageChange = jest.fn();
    const { rerender } = render(
      <Pagination
        page={9}
        count={100}
        rowsPerPage={10}
        onPageChange={onPageChange}
      />
    );

    fireEvent.click(screen.getByRole("button", { name: "Next page" }));
    expect(onPageChange).toHaveBeenCalledWith(expect.anything(), 10);

    // Simulate the controlled parent applying the next page state.
    rerender(
      <Pagination
        page={10}
        count={100}
        rowsPerPage={10}
        onPageChange={onPageChange}
      />
    );

    expect(screen.getByRole("button", { name: "Page 10" })).toHaveFocus();
  });

  it("Moves focus to active first page when previous becomes disabled", () => {
    const onPageChange = jest.fn();
    const { rerender } = render(
      <Pagination
        page={2}
        count={100}
        rowsPerPage={10}
        onPageChange={onPageChange}
      />
    );

    fireEvent.click(screen.getByRole("button", { name: "Previous page" }));
    expect(onPageChange).toHaveBeenCalledWith(expect.anything(), 1);

    // Simulate the controlled parent applying the previous page state.
    rerender(
      <Pagination
        page={1}
        count={100}
        rowsPerPage={10}
        onPageChange={onPageChange}
      />
    );

    expect(screen.getByRole("button", { name: "Page 1" })).toHaveFocus();
  });
});
